{
  "statements": [
    {
      "id": "3.3.2a",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "text (\"Avoid passing\")",
      "text": "a driver SHOULD NOT pass a vehicle WHEN driving in fog",
      "sources": [
        {
          "id": "m45",
          "quote": "Avoid passing, changing lanes and crossing traffic."
        },
        {
          "id": "m47",
          "quote": "Don't pass other vehicles or speed up suddenly."
        }
      ],
      "flags": [
        {
          "code": "X",
          "span": "Avoid passing / Don't pass other vehicles",
          "note": "The same fog-passing prohibition appears in m45 and m47 with different wording."
        }
      ],
      "links": [],
      "note": "Only the passing part of the advice is in scope; changing lanes, crossing traffic and speeding up are omitted."
    },
    {
      "id": "3.3.2b",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"Don't\")",
      "text": "a driver SHOULD NOT speed up to pass a vehicle that is moving slowly WHEN driving in fog",
      "sources": [
        {
          "id": "m46",
          "quote": "Don't speed up to pass a vehicle moving slowly or to get away from a vehicle that is following too closely."
        }
      ],
      "flags": [],
      "links": [],
      "note": "Only the in-scope purpose, passing a vehicle moving slowly, is extracted; the tailgating purpose is out of scope."
    },
    {
      "id": "3.3.3a",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "text (\"Avoid passing\")",
      "text": "a driver SHOULD NOT pass a vehicle WHEN driving in a whiteout",
      "sources": [
        {
          "id": "m48",
          "quote": "Avoid passing, changing lanes and crossing traffic."
        }
      ],
      "flags": [],
      "links": [],
      "note": "Only the passing part of the advice is in scope; changing lanes and crossing traffic are omitted."
    },
    {
      "id": "3.3.3b",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"Don't\")",
      "text": "a driver SHOULD NOT attempt to pass a vehicle that is moving slowly WHEN driving in a whiteout",
      "sources": [
        {
          "id": "m49",
          "quote": "Don't attempt to pass a vehicle moving slowly or speed up to get away from a vehicle that is following too closely."
        }
      ],
      "flags": [],
      "links": [],
      "note": "Only the in-scope part, attempting to pass a vehicle moving slowly, is extracted; the tailgating part is out of scope."
    },
    {
      "id": "3.4.9a",
      "type": "FACT",
      "force": null,
      "force_from": null,
      "text": "FACT several snow plows may be staggered across the road on freeways, clearing all lanes at the same time by passing a ridge of snow from plow to plow",
      "sources": [
        {
          "id": "m73",
          "quote": "On freeways, several snow plows may be staggered across the road, clearing all lanes at the same time by passing a ridge of snow from plow to plow."
        }
      ],
      "flags": [],
      "links": [],
      "note": "This is background for the prohibition in 3.4.9b; \"passing\" here means moving the ridge of snow, not overtaking."
    },
    {
      "id": "3.4.9b",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"Do not try\")",
      "text": "a driver SHOULD NOT try to pass between snow plows WHEN the driver is on a freeway AND several snow plows are staggered across the road BECAUSE there is not [?enough] room to pass [?safely] AND the ridge of wet snow can throw the vehicle out of control",
      "sources": [
        {
          "id": "m73",
          "quote": "On freeways, several snow plows may be staggered across the road, clearing all lanes at the same time by passing a ridge of snow from plow to plow. Do not try to pass between them. This is extremely dangerous because there is not enough room to pass safely, and the ridge of wet snow can throw your vehicle out of control."
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "enough",
          "note": "No measure of space is given."
        },
        {
          "code": "J",
          "span": "safely",
          "note": "Subjective safety with no observable test."
        }
      ],
      "links": [],
      "note": "\"them\" refers to the staggered snow plows."
    }
  ]
}
